"""Task data handling."""

def make_task(title: str, priority: str | None = None) -> dict:
    task = {"title": title}
    if priority is not None:
        task["priority"] = priority
    return task

from tasks import make_task


def create_task(payload: dict) -> dict:
    return make_task(payload["title"], priority=payload.get("priority"))

from api import create_task


def test_create_task():
    assert create_task({"title": "Write docs"}) == {"title": "Write docs"}


def test_create_task_with_priority():
    assert create_task({"title": "Write docs", "priority": "high"}) == {"title": "Write docs", "priority": "high"}
